
#################
# 
# This script loads the SEM tables generated by fit_obspi.R and plots results
# NOTE: this script should be run from within each current_models dir
#
#################

source("~/Devel/bgs_lmr/tools/R_scripts/HelperFunctions.R")
setwd("~/Data/bgs_lmr/PNAS_reviews/cutoff_phastcons/")

cutoff <- c(5, 10, 20, 30, 40)
mutation_maps <- c("carlson", "gnomad", "roulette")

#################
#
# Fit measures & model selection
#
#################

human_maps_10kb <- fread("maps/maps_10kb.csv.gz") 
human_maps_100kb <- fread("maps/maps_100kb.csv.gz") 
human_maps_1Mb <- fread("maps/maps_1Mb.csv.gz") 

# per chromosome SEM models
## 10 kb
chr_fitmeasures_10kb <- data.frame()
for(dag in 3:4) {
  for(co in cutoff) { 
    chr_list <- list(length=num_chrom)
    for(c in 1:num_chrom) {
      
      tmp <- fread(paste("sem/lavaan_out/obspi_YRI_DAG", dag,
                         "_fitmeasures_10kb_chr", 
                         c, "_latents_", co, ".csv", sep=""))
      
      tmp$chrom <- c
      tmp$DAG <- dag
      tmp$cutoff <- co
      
      chr_list[[c]] <- tmp
    }
    
    df <- do.call(rbind.data.frame, chr_list)
    chr_fitmeasures_10kb <- rbind.data.frame(chr_fitmeasures_10kb, df)
  }
}
chr_fitmeasures_10kb$scale <- 1e+4

