p <- ggplot(data=chr_fitmeasures_latent, aes(x=chrom, y=-log10(pvalue), color=as.factor(DAG))) +
  geom_point(size=3) + 
  geom_hline(yintercept=-log10(0.05/num_chrom), linetype="dashed", color="darkgrey") +
  facet_grid(scale/1e3~cutoff) + theme_classic() + 
  scale_y_continuous(breaks=pretty_breaks()) +
  scale_x_continuous(breaks=1:num_chrom) +
  scale_color_manual(values=c("brown1", "cyan3"), name="DAG") +
  labs(title=NULL, x="Chromosome", y=expression(-log[10](italic(p)))) +
  theme(strip.text.y=element_text(size=16),       
        strip.text.x=element_text(size=16),       
        axis.title=element_text(size=16), 
        axis.text=element_text(size=12), 
        axis.text.x=element_text(size=12),
        legend.text=element_text(size=16),
        legend.title=element_text(size=16),
        legend.position="bottom")
save_plot("sem/chr_pvals_latent.pdf", p, base_height=8, base_width=24)

