# summaries
pcs <- filter(chr_params, DAG==4, lhs=="avg_pi", rhs=="avg_mut" | rhs=="B", pvalue < 0.05/22) %>% setDT()
pcs_wd <- dcast(pcs, chrom + DAG + cutoff + scale ~ rhs, value.var = "est") %>% filter(., avg_mut > 0) %>% setDT()
pcs_wd[, ratio:=B/avg_mut]
pcs_wd[, `:=`(min_ratio=min(ratio, na.rm=T), max_ratio=max(ratio, na.rm=T), mean_ratio=mean(ratio, na.rm=T)), 
       by=.(cutoff, scale)]
pcs_wd_unique <- pcs_wd[, .SD[1], by = .(cutoff, scale)]
pcs_wd_unique
# end summaries

chr_params$sig <- chr_params$pvalue < 0.05 / num_chrom # Bonferroni over autosomes
