PC_pi <- filter(chr_params_ext, lhs=="avg_pi") %>% 
  dplyr::select(., c("rhs", "est", "chrom", "DAG", "cutoff", "scale", "sig")) %>% setDT()

setnames(PC_pi, old="rhs", new="Var")
PC_pi <- pivot_wider(PC_pi, names_from=Var, values_from=c(est, sig)) %>% setDT()

chr_r2_pi <- filter(chr_r2_ext_DAGs34) %>%
  dplyr::select(., c("avg_pi", "chrom", "DAG", "pvalue", "cutoff", "scale", "cfi")) %>% setDT()

setnames(chr_r2_pi, old="avg_pi", new="R2_pi")

cutoff_dt <- PC_pi[chr_r2_pi, on = .(chrom, DAG, cutoff, scale)]
cutoff_dt_m <- pivot_longer(cutoff_dt, cols=c(starts_with("est"), "R2_pi", "pvalue", "cfi"), names_to="variable") %>% setDT()
# map significance to the correct estimates
cutoff_dt_m[, sig := fifelse(variable == "est_avg_mut",  sig_avg_mut,
                             fifelse(variable == "est_B", sig_B,
                                     fifelse(variable == "est_prop_del_sites", sig_prop_del_sites, NA)))]
# CFI and R2 don't have p-values
cutoff_dt_m[, variable := factor(variable, levels=c("est_avg_mut", "est_B", "est_prop_del_sites", "cfi", "pvalue", "R2_pi"),
                                           labels=c("u", "B", "E",  "CFI", "p-value", "R^2 * '(' * pi * ')'"))]
cutoff_dt_m[, color_var := fifelse(variable %in% c("u","B","E"), ifelse(sig, "sigTRUE", "sigFALSE"), "metric")]
cutoff_dt_m <- dplyr::select(cutoff_dt_m, c("chrom", "DAG", "cutoff", "scale", "variable", "value", "color_var"))
fwrite(cutoff_dt_m, "sem/summary_SEM.csv")

